create table if not exists public.folders(folder_id bigint generated always as identity primary key,folder_name text not null,parent_id bigint references public.folders(folder_id) on delete set null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),check(parent_id is null or parent_id<>folder_id));
create table if not exists public.document_type(type_id bigint generated always as identity primary key,type_name text not null unique,allowed_extensions text not null,max_file_size_mb numeric(12,2) not null check(max_file_size_mb>0));
create table if not exists public.documents(document_id bigint generated always as identity primary key,file_name text not null,file_path text not null unique,folder_id bigint not null references public.folders(folder_id),type_id bigint not null references public.document_type(type_id),uploaded_by_user_id bigint not null references public.users(user_id),file_size bigint not null check(file_size>=0),mime_type text not null);
create table if not exists public.document_version(version_id bigint generated always as identity primary key,document_id bigint not null references public.documents(document_id) on delete cascade,version_number integer not null check(version_number>0),file_path text not null,uploaded_at timestamptz not null default now(),unique(document_id,version_number));
create table if not exists public.document_relation(relation_id bigint generated always as identity primary key,document_id bigint not null references public.documents(document_id) on delete cascade,target_entity_type text not null,target_entity_id bigint not null,unique(document_id,target_entity_type,target_entity_id));
create table if not exists public.document_permission(permission_id bigint generated always as identity primary key,document_id bigint not null references public.documents(document_id) on delete cascade,role_id bigint references public.roles(role_id),user_id bigint references public.users(user_id),can_read boolean not null default true,can_write boolean not null default false,check(role_id is not null or user_id is not null));
do $$declare t text;begin foreach t in array array['folders','document_type','documents','document_version','document_relation','document_permission'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "documents_select" on public.%I',t);execute format('drop policy if exists "documents_insert" on public.%I',t);execute format('drop policy if exists "documents_update" on public.%I',t);execute format('drop policy if exists "documents_delete" on public.%I',t);execute format('create policy "documents_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "documents_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "documents_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "documents_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
